const r = $input.first().json;
return [{
  json: {
    ok: r.ok,
    returncode: r.returncode,
    command: r.cmd,
    stdout_preview: r.stdout,
    stderr_preview: r.stderr,
    claim_boundary: r.claim_boundary,
    communication_chain: 'GPT-5.5 Planner -> Claude Fable 5 Evidence Critic -> DeepSeek Recovery Agent -> Mistral Verifier/Arbiter',
    generated_at: new Date().toISOString()
  }
}];

const r = $input.first().json;
const text = String(r.stdout_preview || '') + '\n' + String(r.claim_boundary || '');
const forbiddenAsProven = [
  'production O-RAN deployment validation as proven',
  'packet-capture network benchmarking as proven',
  'public-chain benchmarking as proven',
  'full media-plane QoE validation as proven',
  '240-run six-variant ablation as completed'
];
const hits = forbiddenAsProven.filter(x => text.toLowerCase().includes(x.toLowerCase()));
return [{
  json: {
    ...r,
    claim_boundary_review_passed: hits.length === 0,
    forbidden_phrase_hits: hits,
    reviewer_note: hits.length === 0
      ? 'Stage F/F claim-boundary review passed.'
      : 'Unsupported language detected. Inspect before paper use.'
  }
}];
